sys_ui_page.client_script:
(function() {
    var state = {
        cases: [],
        sourceId: null,
        targetId: null,
        assets: [],
        showEmpty: false,
        sourceFilter: '',
        targetFilter: '',
        assetFilter: ''
    };

    var $ = function(id) { return document.getElementById(id); };

    function ajax(method, params, cb) {
        var ga = new GlideAjax('x_1535598_pelican.PelicanCaseAPI');
        ga.addParam('sysparm_name', method);
        Object.keys(params || {}).forEach(function(k) {
            ga.addParam(k, params[k]);
        });
        ga.getXMLAnswer(function(answer) {
            var data;
            try { data = JSON.parse(answer || '{}'); } catch (e) { data = { ok: false, error: 'bad JSON: ' + answer }; }
            cb(data);
        });
    }

    function banner(kind, msg) {
        var b = $('pwb-banner');
        b.className = 'pwb-banner ' + kind;
        b.textContent = msg;
        b.style.display = 'block';
        if (kind === 'success') {
            setTimeout(function() { b.style.display = 'none'; }, 4000);
        }
    }

    function escapeHtml(s) {
        if (s == null) return '';
        return String(s).replace(/[&<>"']/g, function(c) {
            return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]);
        });
    }

    function loadCases() {
        $('pwb-source-list').innerHTML = '<div class="pwb-loading">Loading cases…</div>';
        $('pwb-target-list').innerHTML = '<div class="pwb-loading">Loading cases…</div>';
        ajax('listCases', { sysparm_include_empty: state.showEmpty ? 'true' : 'false' }, function(d) {
            if (!d.ok) { banner('error', d.error || 'Failed to load cases'); return; }
            state.cases = d.cases || [];
            renderSourceList();
            renderTargetList();
        });
    }

    function renderSourceList() {
        var list = $('pwb-source-list');
        var filtered = state.cases.filter(matchesCase(state.sourceFilter));
        if (filtered.length === 0) {
            list.innerHTML = '<div class="pwb-empty">No cases match.</div>';
            return;
        }
        list.innerHTML = filtered.map(function(c) {
            var sel = (c.sys_id === state.sourceId) ? ' selected' : '';
            var pill = c.content_count === 0
                ? '<span class="pwb-pill pwb-pill-empty">empty</span>'
                : '<span class="pwb-pill">' + c.content_count + '</span>';
            return '<div class="pwb-row' + sel + '" data-id="' + c.sys_id + '" data-role="source">' +
                '<div class="pwb-row-main">' +
                '<div class="pwb-row-title">' + escapeHtml(c.asset_tag || c.display_name) + '</div>' +
                '<div class="pwb-row-meta">' + escapeHtml(c.model) + (c.location ? ' · ' + escapeHtml(c.location) : '') + '</div>' +
                '</div>' + pill +
                '</div>';
        }).join('');
    }

    function renderTargetList() {
        var list = $('pwb-target-list');
        var filtered = state.cases.filter(matchesCase(state.targetFilter)).filter(function(c) {
            return c.sys_id !== state.sourceId;
        });
        if (filtered.length === 0) {
            list.innerHTML = '<div class="pwb-empty">No target cases available.</div>';
            return;
        }
        list.innerHTML = filtered.map(function(c) {
            var sel = (c.sys_id === state.targetId) ? ' selected' : '';
            var pill = c.content_count === 0
                ? '<span class="pwb-pill">empty</span>'
                : '<span class="pwb-pill">' + c.content_count + '</span>';
            return '<div class="pwb-row' + sel + '" data-id="' + c.sys_id + '" data-role="target">' +
                '<div class="pwb-row-main">' +
                '<div class="pwb-row-title">' + escapeHtml(c.asset_tag || c.display_name) + '</div>' +
                '<div class="pwb-row-meta">' + escapeHtml(c.model) + (c.location ? ' · ' + escapeHtml(c.location) : '') + '</div>' +
                '</div>' + pill +
                '</div>';
        }).join('');
    }

    function matchesCase(filter) {
        var f = (filter || '').toLowerCase().trim();
        return function(c) {
            if (!f) return true;
            return (c.asset_tag || '').toLowerCase().indexOf(f) !== -1 ||
                   (c.display_name || '').toLowerCase().indexOf(f) !== -1 ||
                   (c.model || '').toLowerCase().indexOf(f) !== -1;
        };
    }

    function loadAssets() {
        if (!state.sourceId) {
            $('pwb-asset-list').innerHTML = '<div class="pwb-empty">Select a source case on the left</div>';
            $('pwb-assets-sub').textContent = 'No case selected';
            updateButtons();
            return;
        }
        $('pwb-asset-list').innerHTML = '<div class="pwb-loading">Loading assets…</div>';
        ajax('getCaseContents', { sysparm_case_id: state.sourceId }, function(d) {
            if (!d.ok) { banner('error', d.error || 'Failed to load assets'); return; }
            state.assets = d.assets || [];
            renderAssets();
        });
    }

    function renderAssets() {
        var list = $('pwb-asset-list');
        var f = state.assetFilter.toLowerCase().trim();
        var filtered = state.assets.filter(function(a) {
            if (!f) return true;
            return (a.asset_tag || '').toLowerCase().indexOf(f) !== -1 ||
                   (a.display_name || '').toLowerCase().indexOf(f) !== -1 ||
                   (a.model || '').toLowerCase().indexOf(f) !== -1;
        });
        var c = state.cases.filter(function(c) { return c.sys_id === state.sourceId; })[0];
        $('pwb-assets-sub').textContent = (c ? (c.asset_tag || c.display_name) + ' — ' : '') + state.assets.length + ' asset' + (state.assets.length === 1 ? '' : 's');

        if (filtered.length === 0) {
            list.innerHTML = '<div class="pwb-empty">' + (state.assets.length === 0 ? 'This case is empty.' : 'No assets match.') + '</div>';
            updateButtons();
            return;
        }
        list.innerHTML = filtered.map(function(a) {
            return '<div class="pwb-row pwb-asset-row" data-id="' + a.sys_id + '" data-role="asset">' +
                '<input type="checkbox" data-asset-id="' + a.sys_id + '"/>' +
                '<div class="pwb-row-main">' +
                '<div class="pwb-row-title">' + escapeHtml(a.asset_tag || a.display_name) + '</div>' +
                '<div class="pwb-row-meta">' + escapeHtml(a.model) + (a.serial_number ? ' · SN ' + escapeHtml(a.serial_number) : '') + '</div>' +
                '</div></div>';
        }).join('');
        updateButtons();
    }

    function selectedAssetIds() {
        return [].slice.call(document.querySelectorAll('#pwb-asset-list input[type=checkbox]:checked'))
            .map(function(cb) { return cb.getAttribute('data-asset-id'); });
    }

    function updateButtons() {
        var n = selectedAssetIds().length;
        $('pwb-selected-count').textContent = n;
        var ready = state.sourceId && state.targetId;
        $('pwb-move').disabled = !ready || n === 0;
        $('pwb-move-all').disabled = !ready || state.assets.length === 0;
    }

    function move(allInSource) {
        if (!state.sourceId || !state.targetId) { banner('error', 'Pick both a source and a target case.'); return; }
        var ids = allInSource ? state.assets.map(function(a) { return a.sys_id; }) : selectedAssetIds();
        if (ids.length === 0) { banner('error', 'Select at least one asset.'); return; }

        var src = state.cases.filter(function(c) { return c.sys_id === state.sourceId; })[0];
        var tgt = state.cases.filter(function(c) { return c.sys_id === state.targetId; })[0];
        if (!confirm('Move ' + ids.length + ' asset' + (ids.length === 1 ? '' : 's') + ' from ' + (src && src.asset_tag) + ' → ' + (tgt && tgt.asset_tag) + '?')) return;

        $('pwb-move').disabled = true;
        $('pwb-move-all').disabled = true;
        ajax('moveAssets', { sysparm_asset_ids: ids.join(','), sysparm_target_case_id: state.targetId }, function(d) {
            if (!d.ok) { banner('error', d.error || 'Move failed'); updateButtons(); return; }
            var msg = 'Moved ' + d.moved + ' asset' + (d.moved === 1 ? '' : 's');
            if (d.errors && d.errors.length) msg += ' (' + d.errors.length + ' error' + (d.errors.length === 1 ? '' : 's') + ')';
            banner('success', msg);
            loadCases();
            loadAssets();
        });
    }

    function init() {
        $('pwb-show-empty').addEventListener('change', function(e) {
            state.showEmpty = e.target.checked;
            loadCases();
        });
        $('pwb-refresh').addEventListener('click', function() {
            loadCases();
            loadAssets();
        });
        $('pwb-source-search').addEventListener('input', function(e) {
            state.sourceFilter = e.target.value;
            renderSourceList();
        });
        $('pwb-target-search').addEventListener('input', function(e) {
            state.targetFilter = e.target.value;
            renderTargetList();
        });
        $('pwb-asset-search').addEventListener('input', function(e) {
            state.assetFilter = e.target.value;
            renderAssets();
        });

        document.addEventListener('click', function(e) {
            var row = e.target.closest && e.target.closest('.pwb-row');
            if (!row) return;
            var role = row.getAttribute('data-role');
            var id = row.getAttribute('data-id');
            if (role === 'source') {
                state.sourceId = id;
                if (state.targetId === id) state.targetId = null;
                renderSourceList();
                renderTargetList();
                loadAssets();
            } else if (role === 'target') {
                state.targetId = id;
                renderTargetList();
                updateButtons();
            }
        });

        document.addEventListener('change', function(e) {
            if (e.target && e.target.matches('#pwb-asset-list input[type=checkbox]')) {
                updateButtons();
            }
        });

        $('pwb-select-all').addEventListener('click', function() {
            [].forEach.call(document.querySelectorAll('#pwb-asset-list input[type=checkbox]'), function(cb) { cb.checked = true; });
            updateButtons();
        });
        $('pwb-select-none').addEventListener('click', function() {
            [].forEach.call(document.querySelectorAll('#pwb-asset-list input[type=checkbox]'), function(cb) { cb.checked = false; });
            updateButtons();
        });

        $('pwb-move').addEventListener('click', function() { move(false); });
        $('pwb-move-all').addEventListener('click', function() { move(true); });

        loadCases();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();
